import{_ as a,c as o,o as r,aj as t}from"./chunks/framework.Id7s26SP.js";const u=JSON.parse('{"title":"Interface: CreateGroupParams","description":"","frontmatter":{},"headers":[],"relativePath":"reference/js-bao-wss-client/api/interfaces/CreateGroupParams.md","filePath":"reference/js-bao-wss-client/api/interfaces/CreateGroupParams.md"}'),s={name:"reference/js-bao-wss-client/api/interfaces/CreateGroupParams.md"};function i(c,e,d,n,l,p){return r(),o("div",null,[...e[0]||(e[0]=[t('<p><a href="./../README.html"><strong>js-bao-wss-client</strong></a></p><hr><p><a href="./../globals.html">js-bao-wss-client</a> / CreateGroupParams</p><h1 id="interface-creategroupparams" tabindex="-1">Interface: CreateGroupParams <a class="header-anchor" href="#interface-creategroupparams" aria-label="Permalink to “Interface: CreateGroupParams”">​</a></h1><p>Parameters for <code>groups.create()</code>. There is no <code>groupId</code>: the server assigns the new group&#39;s id, a ULID, and returns it as <code>groupId</code> on the created <code>GroupInfo</code>. A create whose body sends <code>groupId</code> is refused with 400 <code>GROUP_ID_NOT_ACCEPTED</code>.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="custodian" tabindex="-1">custodian? <a class="header-anchor" href="#custodian" aria-label="Permalink to “custodian?”">​</a></h3><blockquote><p><code>optional</code> <strong>custodian?</strong>: <code>string</code></p></blockquote><p>Who holds the group: <code>app</code>, or <code>user:&lt;userId&gt;</code> for any member of the app. Only a server function or the admin API may name one; a session holds what it creates.</p><hr><h3 id="description" tabindex="-1">description? <a class="header-anchor" href="#description" aria-label="Permalink to “description?”">​</a></h3><blockquote><p><code>optional</code> <strong>description?</strong>: <code>string</code></p></blockquote><p>Optional human-readable description of the group&#39;s purpose</p><hr><h3 id="grouptype" tabindex="-1"><s>groupType?</s> <a class="header-anchor" href="#grouptype" aria-label="Permalink to “groupType?”">​</a></h3><blockquote><p><code>optional</code> <strong>groupType?</strong>: <code>string</code></p></blockquote><p>The group&#39;s stored type; <code>group</code> when omitted.</p><h4 id="deprecated" tabindex="-1">Deprecated <a class="header-anchor" href="#deprecated" aria-label="Permalink to “Deprecated”">​</a></h4><p>Groups are addressed by <code>groupId</code> alone; omit it.</p><hr><h3 id="initialmembers" tabindex="-1">initialMembers? <a class="header-anchor" href="#initialmembers" aria-label="Permalink to “initialMembers?”">​</a></h3><blockquote><p><code>optional</code> <strong>initialMembers?</strong>: <code>object</code>[]</p></blockquote><p>Members written with the group, each <code>manager</code> or <code>member</code> (the default). Only a server function or the admin API may name them.</p><h4 id="role" tabindex="-1">role? <a class="header-anchor" href="#role" aria-label="Permalink to “role?”">​</a></h4><blockquote><p><code>optional</code> <strong>role?</strong>: <code>&quot;member&quot;</code> | <code>&quot;manager&quot;</code></p></blockquote><h4 id="userid" tabindex="-1">userId <a class="header-anchor" href="#userid" aria-label="Permalink to “userId”">​</a></h4><blockquote><p><strong>userId</strong>: <code>string</code></p></blockquote><hr><h3 id="initialmetadata" tabindex="-1">initialMetadata? <a class="header-anchor" href="#initialmetadata" aria-label="Permalink to “initialMetadata?”">​</a></h3><blockquote><p><code>optional</code> <strong>initialMetadata?</strong>: <code>Record</code>&lt;<code>string</code>, <code>Record</code>&lt;<code>string</code>, <code>unknown</code>&gt;&gt;</p></blockquote><p>Optional. Create-time resource metadata to stamp on the new group, keyed by category name → the category&#39;s values. Each entry is schema-validated but the category <code>writeRule</code> is waived — creation authority covers the initial stamp. At most 10 categories; any invalid entry fails the whole create. The stamp only writes fresh rows: a row already stored for the new group&#39;s id and category fails the create with 409 <code>METADATA_EXISTS</code>.</p><hr><h3 id="name" tabindex="-1">name <a class="header-anchor" href="#name" aria-label="Permalink to “name”">​</a></h3><blockquote><p><strong>name</strong>: <code>string</code></p></blockquote><p>Display name for the group</p><hr><h3 id="settings" tabindex="-1">settings? <a class="header-anchor" href="#settings" aria-label="Permalink to “settings?”">​</a></h3><blockquote><p><code>optional</code> <strong>settings?</strong>: <code>Partial</code>&lt;<a href="./GroupSettings.html"><code>GroupSettings</code></a>&gt;</p></blockquote><p>The group&#39;s settings; <code>memberList: &quot;members&quot;</code> when omitted.</p>',39)])])}const m=a(s,[["render",i]]);export{u as __pageData,m as default};
